"use client"

/**
 * Agent UI — explicit business action wrapper.
 *
 * Generic buttons do not automatically become callable agent actions (spec
 * section 6: business semantics are never inferred from presentation).
 * `AgentAction` registers a capability of kind `"action"` that the WebMCP
 * adapter exposes as a dedicated tool. It is a semantics wrapper, not a UI
 * element — it renders its children unchanged.
 */

import * as React from "react"
import type { CapabilityState } from "./capability"
import { useCapability, type ActionMap } from "./use-capability"
import { expectBoolean, rejectState } from "./validate"

/**
 * The WebMCP tool for a business action is named `action_<id>`. Chrome caps a
 * tool name at 30 characters, so the id is capped at 23 and restricted to the
 * WebMCP name charset. Truncating silently could collide with another action
 * and make its registration fail, so an invalid id is refused instead.
 */
const ACTION_ID = /^[A-Za-z0-9_.-]{1,23}$/

export interface AgentActionProps {
  id: string
  description: string
  execute: (input: Record<string, unknown>) => unknown | Promise<unknown>
  /** JSON Schema `properties` for the action's own arguments. */
  inputSchema?: Record<string, unknown>
  /**
   * Consequential actions opt into confirmation. The agent must then pass
   * `confirmed: true`; anything else is rejected with this message.
   */
  confirm?: string
  children?: React.ReactNode
}

interface ActionState extends CapabilityState {
  description: string
  inputSchema?: Record<string, unknown>
  requiresConfirmation: boolean
  lastResult: unknown
}

type ActionActions = { run: Record<string, unknown> }

export function AgentAction(props: AgentActionProps): React.ReactNode {
  const { id, description, execute, inputSchema, confirm, children } = props

  if (!ACTION_ID.test(id)) {
    throw new Error(
      `Agent UI: AgentAction id "${id}" is invalid. Use 1-23 characters from A-Z, a-z, 0-9, "_", "-" or ".".`,
    )
  }

  // Held in a ref and surfaced only through `read()`, so React state remains
  // canonical and the registry never stores a second copy.
  const lastResultRef = React.useRef<unknown>(undefined)

  const read = React.useCallback((): ActionState => {
    return {
      description,
      inputSchema,
      requiresConfirmation: confirm !== undefined,
      lastResult: lastResultRef.current,
    }
  }, [description, inputSchema, confirm])

  const actions = React.useMemo<ActionMap<ActionActions>>(
    () => ({
      async run(input: Record<string, unknown>): Promise<unknown> {
        let payload: Record<string, unknown> = input
        if (confirm !== undefined) {
          const confirmed = expectBoolean(input, "confirmed")
          if (!confirmed) {
            rejectState(confirm)
          }
          payload = { ...input }
          delete payload.confirmed
        }
        const result = await execute(payload)
        lastResultRef.current = result
        return result
      },
    }),
    [execute, confirm],
  )

  useCapability<ActionState, ActionActions>({
    agent: { id, label: id },
    kind: "action",
    read,
    actions,
  })

  return children
}

"use client"

/**
 * Agent UI — containment context.
 *
 * A capability rendered inside another capability's subtree usually belongs
 * to that container: a checkbox in a table row belongs to the table, not to
 * the page as one more anonymous root. The container tells the capabilities
 * rendered inside it who they belong to through this context, and
 * `useCapability` fills in from it whatever the caller did not state
 * explicitly. The context knows about containment — owner, position, order —
 * and nothing about any particular component.
 */

import * as React from "react"

export interface AgentContainer {
  /** Capability id of the container. Becomes each descendant's `owner`. */
  ownerId: string | undefined
  /**
   * What this position within the container is, e.g.
   * "row 3: ada@lovelace.dev". A container whose position name lives in text
   * that only exists once its subtree is mounted — a table row's first cell
   * — supplies a resolver instead of a string; the resolver runs when a
   * descendant capability registers, never during render.
   */
  itemLabel?: string | (() => string)
  /**
   * What this position is called for IDENTITY, e.g. "ada@lovelace.dev" — the
   * item and nothing else, with no position in it. A descendant's id is
   * derived from this while its label is composed from `itemLabel`, so the
   * label can tell an agent where to look ("row 3") while the id survives
   * sorting and paging. Same resolver contract as `itemLabel`. When a
   * container supplies no `itemKey`, identity falls back to `itemLabel`.
   */
  itemKey?: string | (() => string | undefined)
}

/**
 * Full shape of the context value. `claimItemPosition` is machinery for a
 * container that renders an ordered sequence of item slots (a table body):
 * a child occupying a slot claims its 1-based position by calling it once
 * during its own render, keyed by an identity stable across the render's
 * invocations, so a lone re-render of the child returns the position it
 * already holds and a fresh pass renumbers from 1.
 */
interface ContainerValue extends AgentContainer {
  claimItemPosition?: (identity: string) => number
}

const AgentContainerContext = React.createContext<ContainerValue | null>(null)

/**
 * Nesting composes: a provider inside a provider inherits `ownerId` and
 * `itemLabel` from the outer one unless it sets its own. That is what lets
 * `Table` set the owner once and `TableRow` set only the item it renders.
 */
export function AgentContainerProvider({
  ownerId,
  itemLabel,
  itemKey,
  claimItemPosition,
  children,
}: {
  ownerId?: string
  itemLabel?: string | (() => string)
  itemKey?: string | (() => string | undefined)
  claimItemPosition?: (identity: string) => number
  children: React.ReactNode
}) {
  const outer = React.useContext(AgentContainerContext)
  // Memoized so a container re-rendering for an unrelated reason (its own
  // capability registering) keeps the value identical and does not drag every
  // consumer in its subtree into a render it did not need.
  const value = React.useMemo<ContainerValue>(
    () => ({
      ownerId: ownerId ?? outer?.ownerId,
      itemLabel: itemLabel ?? outer?.itemLabel,
      itemKey: itemKey ?? outer?.itemKey,
      ...(claimItemPosition ? { claimItemPosition } : {}),
    }),
    [ownerId, itemLabel, itemKey, claimItemPosition, outer],
  )
  return (
    <AgentContainerContext.Provider value={value}>
      {children}
    </AgentContainerContext.Provider>
  )
}

/**
 * The container the calling capability sits in, or null when there is none —
 * a capability outside any container is an ordinary root, not an error.
 */
export function useAgentContainer(): AgentContainer | null {
  return React.useContext(AgentContainerContext)
}

/**
 * Claims the calling component's 1-based position in the ordered item
 * sequence its container renders, or null when no container offers one. The
 * component that occupies the slot calls this once per render; the claim is
 * keyed by the component's own identity, so a re-render — including
 * StrictMode's double invocation — returns the position already held instead
 * of taking another.
 */
export function useAgentItemPosition(): number | null {
  const container = React.useContext(AgentContainerContext)
  const identity = React.useId()
  return container?.claimItemPosition?.(identity) ?? null
}

"use client"

/**
 * Agent UI — explicit content wrapper.
 *
 * Content the application renders itself — a chart, a paragraph, a whole
 * panel of markup — carries no capability, so discovery never reports it and
 * an agent cannot read a word of it. `AgentContent` is the escape hatch: it
 * registers a capability of kind `"content"` whose `read()` reports the
 * normalised text of its own subtree. Like `AgentAction`, it is a semantics
 * wrapper, not a UI element — it renders its children unchanged.
 */

import * as React from "react"

import { useCapability, type AgentProp } from "@/lib/agent-ui/use-capability"
import { useMergedRef } from "@/lib/agent-ui/use-merged-ref"

/**
 * Tags that end a line of reading.
 *
 * `textContent` concatenates with no separator, so a card whose value and
 * delta sit in sibling blocks reads as "$45,231.89+20.1% from last month" —
 * two facts fused into one token that an agent can misparse as arithmetic.
 * Boundaries are restored from the tag name rather than from layout: asking
 * for computed styles would make the cost of a read grow with the size of the
 * subtree being read, on a path an agent calls.
 */
const BLOCK_TAGS = new Set([
  "ADDRESS", "ARTICLE", "ASIDE", "BLOCKQUOTE", "BR", "DD", "DIV", "DL", "DT",
  "FIELDSET", "FIGCAPTION", "FIGURE", "FOOTER", "FORM", "H1", "H2", "H3", "H4",
  "H5", "H6", "HEADER", "HR", "LI", "MAIN", "NAV", "OL", "P", "PRE", "SECTION",
  "TABLE", "TBODY", "TD", "TFOOT", "TH", "THEAD", "TR", "UL",
])

// DOM node type constants, spelled out because `Node` is not a global in
// every environment these components are read in.
const TEXT_NODE = 3
const ELEMENT_NODE = 1

function collectText(node: Node, into: string[]): void {
  if (node.nodeType === TEXT_NODE) {
    into.push(node.nodeValue ?? "")
    return
  }
  if (node.nodeType !== ELEMENT_NODE) return
  const isBlock = BLOCK_TAGS.has((node as Element).tagName)
  if (isBlock) into.push(" ")

  // Two element siblings with nothing between them are two separate things a
  // person sees held apart by layout: `<span>Active</span><span>127</span>`
  // reads as "Active127" through textContent. An element sitting *between*
  // text is the opposite case — the bold in "Hello <b>world</b>!" is one
  // phrase — so the separator goes only between adjacent elements.
  let previousWasElement = false
  for (const child of node.childNodes) {
    if (child.nodeType === ELEMENT_NODE) {
      if (previousWasElement) into.push(" ")
      previousWasElement = true
    } else if (
      child.nodeType === TEXT_NODE &&
      (child.nodeValue ?? "").trim() !== ""
    ) {
      previousWasElement = false
    }
    collectText(child, into)
  }

  if (isBlock) into.push(" ")
}

/**
 * Reads an element's text the way a person reads it: block boundaries become
 * spaces, whitespace runs collapse to one, and the result is capped at
 * `maxLength` with a trailing ellipsis. Every content capability — card
 * fields, table cells, an `AgentContent` subtree — reports text through this
 * one shape. An absent element reads as the empty string.
 */
export function readText(element: Element | null | undefined, maxLength: number): string {
  if (!element) return ""
  const parts: string[] = []
  collectText(element, parts)
  const text = parts.join("").trim().replace(/\s+/g, " ")
  return text.length > maxLength ? `${text.slice(0, maxLength)}…` : text
}

/** Cap for the text reported for the wrapper's whole subtree. */
const SUBTREE_MAX_LENGTH = 2000

export interface AgentContentProps extends React.ComponentProps<"div"> {
  /** The capability's label, shown by `ui_list`. */
  label: string
  /** What the content is; reported with every read, like AgentAction's. */
  description?: string
  /**
   * The content as data, for content a person reads but text cannot carry.
   *
   * A chart is the case this exists for: its numbers are geometry, so the
   * subtree's text is empty however carefully it is read. The application
   * already holds the series it passed to the chart library, so it states it
   * here rather than having anything try to reconstruct it from the SVG.
   * Must be JSON-serialisable.
   */
  value?: unknown
  agent?: AgentProp
}

type AgentContentState = {
  text: string
  description: string | null
  value: unknown
}

export function AgentContent({
  label,
  description,
  value,
  agent,
  ref,
  ...props
}: AgentContentProps) {
  const elementRef = React.useRef<HTMLDivElement>(null)
  const mergedRef = useMergedRef(ref, elementRef)

  // Reads are pull-based: they run only when an agent calls ui_list or
  // ui_read, never on render and never in an effect. That is what makes
  // registering a whole content subtree affordable.
  useCapability<AgentContentState, Record<string, never>>({
    agent,
    kind: "content",
    defaultLabel: label,
    read: () => ({
      text: readText(elementRef.current, SUBTREE_MAX_LENGTH),
      description: description ?? null,
      // Reported unconditionally: an agent must be able to tell content that
      // carries no data from content whose data happens to be absent.
      value: value ?? null,
    }),
    actions: {},
  })

  return <div ref={mergedRef} data-slot="agent-content" {...props} />
}

"use client"

import * as React from "react"

import type { AgentConfig, AgentProp } from "./use-capability"

/**
 * Agent UI — identity and naming helpers for agent-operable components.
 *
 * The ordinary shadcn way of writing a form already carries both facts an
 * agent needs: an `id` for addressing and a `<label>` for description. These
 * helpers let a component read its own identity and its own name from what
 * the application already wrote, so the application needs no `agent` prop.
 *
 * Two facts, kept separate:
 *
 *  - `id` is canonical addressing: `agent.id` → the component's own `id`
 *    prop → a generated document-local id.
 *  - `label` is description: `agent.label` → `aria-label` →
 *    `aria-labelledby` → the associated `<label>` → the element's own text
 *    (a button or link's visible text is its native accessible name) → an
 *    intrinsic fallback.
 *
 * Never use the label as the id.
 */

/**
 * Fills in `id` from the element's own id attribute, without overriding an
 * explicit `agent.id`.
 *
 * Returns `false` unchanged — opting out stays opting out. Otherwise resolves
 * the prop to its config form and fills in `id` from `elementId` only when
 * the config does not already carry one. An explicit `agent.id` always wins.
 */
export function agentWithElementId(
  agent: AgentProp | undefined,
  elementId: string | undefined,
): AgentProp | undefined {
  if (agent === false) return false

  const config: AgentConfig =
    agent === true || agent === undefined ? {} : { ...agent }

  if (config.id === undefined && elementId !== undefined) {
    config.id = elementId
  }

  return config
}

/** Maximum length of a resolved accessible name. */
const NAME_MAX_LENGTH = 100

/**
 * Normalises text: trim, collapse internal whitespace runs to single
 * spaces. Returns null for an empty result so the caller can fall through.
 */
function normaliseText(text: string | null | undefined): string | null {
  if (text === null || text === undefined) return null
  const trimmed = text.trim()
  if (trimmed === "") return null
  return trimmed.replace(/\s+/g, " ")
}

/** Caps text at NAME_MAX_LENGTH characters. */
function capLength(text: string): string {
  return text.length > NAME_MAX_LENGTH ? text.slice(0, NAME_MAX_LENGTH) : text
}

/**
 * Resolves the accessible name of a mounted element, in this precedence:
 *
 * 1. `aria-label`, when non-empty after trimming.
 * 2. `aria-labelledby`: for each id in the attribute, the `textContent` of
 *    `document.getElementById(id)`, joined with a single space.
 * 3. The associated `<label>`: the element's `labels` collection when it has
 *    one (real form controls do); otherwise, when the element has an `id`,
 *    the first `label[for="<id>"]` in the document; otherwise
 *    `element.closest("label")`. Take its `textContent`.
 * 4. The element's own subtree text, for elements whose native accessible
 *    name IS that text: `<button>`, `<a>`, and the menu-item roles, which
 *    the accessible-name specification names as taking their name from
 *    content. Other elements keep their own native mechanisms — a
 *    `<select>`'s name is never its options' text, a `<textarea>`'s never
 *    its default value — so their text content is not a name source.
 * 5. `fallback`.
 *
 * Each source is normalised (trim, collapse whitespace) and an empty result
 * falls through to the next source. The final result is capped at
 * NAME_MAX_LENGTH characters.
 */
/**
 * The surface of an element a name is read from — deliberately minimal and
 * structural. The helper reads attributes, labels and text and nothing else,
 * so it accepts a ref to any element. A nominal `HTMLElement` parameter
 * would refuse some elements outright: wrangler's generated worker types
 * merge an HTMLRewriter `Element` into the DOM lib's, which breaks
 * `HTMLSelectElement extends HTMLElement` assignability over the `remove()`
 * overloads — a member this helper never touches.
 */
interface NamedElement {
  id: string
  tagName: string
  textContent: string | null
  getAttribute(name: string): string | null
  closest(selectors: string): { textContent: string | null } | null
}

function resolveAccessibleName(element: NamedElement, fallback: string): string {
  // 1. aria-label
  const ariaLabel = normaliseText(element.getAttribute("aria-label"))
  if (ariaLabel !== null) return capLength(ariaLabel)

  // 2. aria-labelledby
  const labelledBy = element.getAttribute("aria-labelledby")
  if (labelledBy) {
    const text = labelledBy
      .split(/\s+/)
      .filter(Boolean)
      .map((id) => document.getElementById(id))
      .filter((target): target is HTMLElement => target !== null)
      .map((target) => target.textContent ?? "")
      .join(" ")
    const label = normaliseText(text)
    if (label !== null) return capLength(label)
  }

  // 3. Associated <label>
  // 3a. labels collection (real form controls)
  if ("labels" in element) {
    const labels = (element as HTMLInputElement).labels
    if (labels && labels.length > 0) {
      const label = normaliseText(labels[0]?.textContent)
      if (label !== null) return capLength(label)
    }
  }

  // 3b. label[for="<id>"]
  if (element.id) {
    const escapedId = element.id.replace(/["\\]/g, "\\$&")
    const labelEl = document.querySelector(`label[for="${escapedId}"]`)
    if (labelEl) {
      const label = normaliseText(labelEl.textContent)
      if (label !== null) return capLength(label)
    }
  }

  // 3c. closest("label")
  const closestLabel = element.closest("label")
  if (closestLabel) {
    const label = normaliseText(closestLabel.textContent)
    if (label !== null) return capLength(label)
  }

  // 4. The element's own subtree text — a button or link's visible text, or
  // a menu item's, whose role takes its name from content.
  const role = element.getAttribute("role")
  if (
    element.tagName === "BUTTON" ||
    element.tagName === "A" ||
    role === "menuitem" ||
    role === "menuitemcheckbox" ||
    role === "menuitemradio"
  ) {
    const label = normaliseText(element.textContent)
    if (label !== null) return capLength(label)
  }

  // 5. fallback
  return capLength(fallback)
}

/**
 * Returns `fallback` until the element is mounted, then the element's
 * accessible name resolved from the DOM.
 *
 * Resolved in `useLayoutEffect` with no dependency array, so it runs on every
 * commit and follows a label whose text changes. The element does not exist
 * during render, and reading layout-adjacent DOM before paint is what layout
 * effects are for. The setter is called only when the resolved value actually
 * differs from what is already in state, otherwise every commit would
 * schedule a render and the component would loop.
 *
 * This reads the DOM for a *name*, never to drive a transition — dispatch
 * still goes registry → capability → component.
 */
export function useAccessibleName(
  ref: React.RefObject<NamedElement | null>,
  fallback: string,
): string {
  const [name, setName] = React.useState(fallback)

  React.useLayoutEffect(() => {
    const element = ref.current
    if (!element) return

    const resolved = resolveAccessibleName(element, fallback)
    if (resolved !== name) {
      setName(resolved)
    }
  })

  return name
}

"use client"

/**
 * Agent UI — page identity.
 *
 * A person knows what a page is for before reading a single control: the
 * heading says "User List", the subheading says what it manages. An agent gets
 * a list of elements and has to infer the page from their shapes. Asked what
 * it had landed on, a blind operator answered by recognising the KPI card
 * titles — a guess that happened to be right.
 *
 * `AgentPage` is how a page says what it is. It registers a capability of kind
 * `"page"`, which `ui_list` promotes into the document's `page` field instead
 * of listing as an element: it is the header of the document, not a thing on
 * it. It renders nothing, so it can be dropped anywhere in the route.
 */

import { useCapability, type AgentProp } from "@/lib/agent-ui/use-capability"

export interface AgentPageProps {
  /** What this page is, as its heading says it. */
  title: string
  /** What a person does here, in one sentence. */
  description?: string
  agent?: AgentProp
}

type AgentPageState = {
  title: string
  description: string | null
  /** Where the page is, so an agent that followed a redirect knows where it landed. */
  path: string | null
}

export function AgentPage({ title, description, agent }: AgentPageProps): null {
  // Read pull-based, when an agent asks. The path is a fact the document owns;
  // reporting it costs nothing and saves an agent inferring where it is.
  useCapability<AgentPageState, Record<string, never>>({
    agent,
    kind: "page",
    defaultLabel: title,
    description,
    read: () => ({
      title,
      description: description ?? null,
      // `window.location`, not the bare global: a host may install the
      // document without installing every global that a browser also has.
      path: typeof window === "undefined" ? null : window.location.pathname,
    }),
    actions: {},
  })

  return null
}

/**
 * Agent UI — capability kernel.
 *
 * A capability is one mounted semantic UI surface. It knows nothing about
 * WebMCP, shadcn, the DOM, the CLI or codemods. It only knows how to report
 * its own semantic state and how to perform its own semantic actions.
 */

/** Semantic state and action result of a capability, always JSON-serialisable. */
export type CapabilityState = Record<string, unknown>

export interface Capability<
  State extends CapabilityState = CapabilityState,
  Actions extends Record<string, unknown> = Record<string, unknown>,
> {
  id: string
  kind: string
  label?: string
  /** What this specific element is for, one sentence. Instance-specific. */
  description?: string
  /** id of the capability that contains this one, when it is nested. */
  owner?: string

  /**
   * Names of the actions this capability supports. Discovery cannot be
   * reconstructed from anywhere else, so the capability declares it.
   */
  actions: readonly (keyof Actions & string)[]

  read(): State

  /**
   * One-line digest of current state, when the component can say it better
   * than a generic formatter can.
   */
  summarise?(): string | undefined

  invoke<Action extends keyof Actions & string>(
    action: Action,
    input: Actions[Action],
  ): Promise<CapabilityResult<State>>
}

/**
 * Result of one semantic action.
 *
 * `state` is read from the component *after* the application has committed the
 * transition, so it is the canonical post-transition state — never a
 * manufactured echo of the request.
 */
export interface CapabilityResult<State extends CapabilityState = CapabilityState> {
  state: State
  /** Optional action-specific return value, e.g. how many rows matched. */
  detail?: unknown
}

/** Machine-readable reasons a semantic dispatch was rejected. */
export type CapabilityErrorCode =
  | "unknown_target"
  | "unsupported_action"
  | "invalid_input"
  | "rejected"

/**
 * Rejection of an agent request. The message is written for an agent to
 * self-correct from and must never carry stack traces, provider names or
 * other internals.
 */
export class CapabilityError extends Error {
  readonly code: CapabilityErrorCode

  constructor(code: CapabilityErrorCode, message: string) {
    super(message)
    this.name = "CapabilityError"
    this.code = code
  }
}

/** Discovery descriptor produced by the registry, never by a component. */
export interface CapabilityDescriptor {
  id: string
  kind: string
  label?: string
  description?: string
  owner?: string
  actions: readonly string[]
}

export function describe(capability: Capability): CapabilityDescriptor {
  // Absent optional fields are left off the descriptor entirely, so a
  // descriptor never carries an `undefined` placeholder.
  const descriptor: CapabilityDescriptor = {
    id: capability.id,
    kind: capability.kind,
    actions: capability.actions,
  }
  if (capability.label !== undefined) descriptor.label = capability.label
  if (capability.description !== undefined) {
    descriptor.description = capability.description
  }
  if (capability.owner !== undefined) descriptor.owner = capability.owner
  return descriptor
}

/**
 * Agent UI — capability registry.
 *
 * Exactly one live registry per document runtime. Registration defines
 * availability; unregistration defines disappearance. There is no
 * reconciliation loop, no DOM scan and no shadow inventory.
 */

import {
  CapabilityError,
  describe,
  type Capability,
  type CapabilityDescriptor,
  type CapabilityResult,
  type CapabilityState,
} from "./capability"

export interface CapabilityRegistry {
  register(capability: Capability): () => void
  get(id: string): Capability | undefined
  /**
   * The capability with this id, or a refusal an agent can correct from.
   *
   * `get` is for a caller that treats absence as ordinary — a UI reading a
   * stale snapshot. `require` is for a caller acting on an agent's request,
   * where absence is something the agent must be told about. Neither reads
   * state: resolving an id must not cost what reading it costs.
   */
  require(id: string): Capability
  list(): Capability[]
  listByKind(kind: string): Capability[]
  listKinds(): string[]
  /** Stable snapshot of every live capability, replaced only when the set changes. */
  describeAll(): CapabilityDescriptor[]
  /** Canonical semantic state of one capability. */
  read(id: string): CapabilityState
  invoke(id: string, action: string, input: unknown): Promise<CapabilityResult>
  /** Notified whenever the set of live capabilities changes. */
  subscribe(listener: () => void): () => void
  /** Document-local identity for a capability that resolved no label. */
  createId(kind: string, seed: string): string
  /**
   * Reserves a deterministic document-local id derived from what the
   * capability can say about itself: `[owner, kind, slug(source)]`, joined
   * with dots, capped at 120 characters and stripped to tool-name-safe
   * characters.
   *
   * Two capabilities may derive the same base — two "Delete" buttons under
   * one owner — so the id is made unique with a numeric discriminator: the
   * first instance takes the bare base, later ones `base.2`, `base.3`, ….
   *
   * The discriminator belongs to the capability INSTANCE (`seed` — React's
   * useId, stable for the instance's lifetime), not to the moment of
   * registration: the registry remembers the number each seed held, and a
   * re-registering instance reclaims it no matter how registration and
   * unregistration interleave. That is what defeats the case where a new
   * capability registers before its predecessor unregisters — there,
   * "append the next free number" hands out a different id and the churn
   * this scheme exists to remove comes straight back. A fresh instance takes
   * the lowest number no live capability holds and forgets the dead instance
   * that held it, so the memory per base stays bounded by the base's peak
   * live instances and a remount — a dialog closed and reopened, whose
   * content carries new seeds — numbers from 1 again and lands on the ids it
   * had before.
   */
  deriveId(
    owner: string | undefined,
    kind: string,
    source: string,
    seed: string,
  ): string
}

/** Characters an id may carry and still be a safe tool name. */
const UNSAFE_ID_CHARACTERS = /[^a-zA-Z0-9_.-]/g

/** A derived id is capped so a long label cannot produce an unbounded name. */
const DERIVED_ID_MAX_LENGTH = 120

/**
 * Reduces a resolved label to the slug a derived id carries:
 * "Invite User" → "invite-user". Runs of anything outside latin letters and
 * digits collapse into one separator, so the result stays tool-name-safe.
 */
function slugify(text: string): string {
  return text
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
}

/** The base id itself for discriminator 1, `base.2`, `base.3`, … after it. */
function numberedId(base: string, number: number): string {
  return number === 1 ? base : `${base}.${number}`
}

/**
 * How many ids a refusal names. The message exists to be read, so it has to
 * stay small enough to survive a tool's output budget: listing every id turned
 * a correctable "no such element" into `output_too_large` on a page with a few
 * hundred elements, and the agent lost the one thing that would have unstuck
 * it. Ten is enough to spot a typo; `ui_list` is the way to see them all.
 */
const SUGGESTION_LIMIT = 10

/** Length of the prefix two ids share, used to put likely typos first. */
function sharedPrefixLength(a: string, b: string): number {
  const limit = Math.min(a.length, b.length)
  let shared = 0
  while (shared < limit && a[shared] === b[shared]) shared += 1
  return shared
}

function unknownTargetMessage(id: string, known: string[]): string {
  if (known.length === 0) {
    return `No UI element with id "${id}" is on the page. There are no agent-operable elements right now.`
  }
  // Nearest first, so a mistyped or stale id sits next to the one meant. Ties
  // break on the shorter id: an owner is a likelier intent than its contents.
  const nearest = [...known].sort((a, b) => {
    const byPrefix = sharedPrefixLength(id, b) - sharedPrefixLength(id, a)
    return byPrefix !== 0 ? byPrefix : a.length - b.length
  })
  const shown = nearest.slice(0, SUGGESTION_LIMIT)
  const rest = known.length - shown.length
  const tail =
    rest > 0
      ? `, and ${rest} more — call ui_list to see them all.`
      : "."
  return `No UI element with id "${id}" is on the page. Closest ids: ${shown.join(", ")}${tail}`
}

function createRegistry(): CapabilityRegistry {
  const capabilities = new Map<string, Capability>()
  const listeners = new Set<() => void>()
  // Per derived base: the discriminator number each capability instance (its
  // React useId seed) held when it last registered. Entries are forgotten
  // when a fresh instance reuses their number, which keeps the memory per
  // base bounded by the base's peak live instances.
  const derivedNumbers = new Map<string, Map<string, number>>()

  // Snapshot for `useSyncExternalStore`. Held here because the registry is the
  // only thing that knows when the set of capabilities actually changed.
  let snapshot: CapabilityDescriptor[] | undefined

  const notify = () => {
    snapshot = undefined
    for (const listener of [...listeners]) listener()
  }

  const requireCapability = (id: string): Capability => {
    const capability = capabilities.get(id)
    if (!capability) {
      throw new CapabilityError("unknown_target", unknownTargetMessage(id, [...capabilities.keys()]))
    }
    return capability
  }

  return {
    register(capability) {
      const existing = capabilities.get(capability.id)
      if (existing && existing !== capability) {
        throw new Error(
          `Agent UI: duplicate capability id "${capability.id}". ` +
            `Every mounted capability must have exactly one identity — give one of them a distinct \`agent.id\`.`,
        )
      }
      capabilities.set(capability.id, capability)
      notify()
      return () => {
        if (capabilities.get(capability.id) === capability) {
          capabilities.delete(capability.id)
          notify()
        }
      }
    },

    get(id) {
      return capabilities.get(id)
    },

    require(id) {
      return requireCapability(id)
    },

    list() {
      return [...capabilities.values()]
    },

    listByKind(kind) {
      return [...capabilities.values()].filter((c) => c.kind === kind)
    },

    listKinds() {
      return [...new Set([...capabilities.values()].map((c) => c.kind))].sort()
    },

    describeAll() {
      snapshot ??= [...capabilities.values()].map(describe)
      return snapshot
    },

    read(id) {
      return requireCapability(id).read()
    },

    async invoke(id, action, input) {
      const capability = requireCapability(id)
      if (!capability.actions.includes(action)) {
        throw new CapabilityError(
          "unsupported_action",
          `"${id}" is a ${capability.kind} and does not support "${action}". Supported actions: ${capability.actions.join(", ")}.`,
        )
      }
      return capability.invoke(action, input as never)
    },

    subscribe(listener) {
      listeners.add(listener)
      return () => {
        listeners.delete(listener)
      }
    },

    createId(kind, seed) {
      return `${kind}_${seed.replace(/[^a-zA-Z0-9_-]/g, "")}`
    },

    deriveId(owner, kind, source, seed) {
      const base = [owner, kind, slugify(source)]
        .filter((part) => part !== undefined && part !== "")
        .join(".")
        .replace(UNSAFE_ID_CHARACTERS, "")
        .slice(0, DERIVED_ID_MAX_LENGTH)
      let numbers = derivedNumbers.get(base)
      if (!numbers) {
        numbers = new Map()
        derivedNumbers.set(base, numbers)
      }

      // A re-registering instance reclaims the discriminator it held.
      const remembered = numbers.get(seed)
      if (remembered !== undefined) {
        const candidate = numberedId(base, remembered)
        if (!capabilities.has(candidate)) return candidate
        // The seed's slot is held by another live capability — two document
        // roots can share a useId seed — so this registration takes a fresh
        // number below without displacing the remembered one.
      }

      // A fresh instance takes the lowest number no live capability holds;
      // the dead instance that held it is forgotten.
      let number = 1
      while (capabilities.has(numberedId(base, number))) number += 1
      for (const [holder, held] of numbers) {
        if (held === number) {
          numbers.delete(holder)
          break
        }
      }
      numbers.set(seed, number)
      return numberedId(base, number)
    },
  }
}

const REGISTRY_KEY = Symbol.for("agent-ui.capability-registry")

type RegistryHost = { [REGISTRY_KEY]?: CapabilityRegistry }

/**
 * The single live registry for this document runtime. Keyed off a global
 * symbol so module duplication (HMR, multiple bundles) still resolves to one
 * canonical index.
 */
export function getCapabilityRegistry(): CapabilityRegistry {
  const host = globalThis as RegistryHost
  const existing = host[REGISTRY_KEY]
  if (existing) return existing
  const registry = createRegistry()
  host[REGISTRY_KEY] = registry
  return registry
}

/**
 * Agent UI — protocol-independent tool definitions.
 *
 * This file is deliberately separate from `webmcp.ts`: it defines the agent
 * tool surface as plain data plus executors that dispatch exclusively through
 * the capability registry. It never references `document.modelContext`, so the
 * gallery playground can execute exactly the same definitions against the same
 * registry without a WebMCP-capable browser. `webmcp.ts` is the thin protocol
 * adapter that registers these tools with the browser; everything semantic
 * lives here.
 */

