/**
 * Output budget for one tool result.
 *
 * This is our own choice, not a rule from anywhere else: the WebMCP
 * specification says nothing about output length (it constrains *input*
 * lengths, in its security mitigations, and leaves output to the
 * implementation), and Chrome's guidance asks only that results be
 * "written clearly and formatted correctly". A bound still belongs here —
 * an unbounded result would spend the agent's context on one call — but it
 * has to be wide enough for the state of a real component. A table's
 * columns, paging, sort, filters, selection and visible rows do not fit in
 * a couple of thousand characters, and a read that cannot return its own
 * subject is worthless.
 */
const MAX_OUTPUT = 8000

/** Longest string a digest keeps verbatim before cutting it. */
const DIGEST_STRING_LIMIT = 80

/** Longest scalar array a digest keeps whole; longer ones become `{items}`. */
const DIGEST_ARRAY_LIMIT = 8

function isScalar(value: unknown): boolean {
  return (
    value === null ||
    typeof value === "string" ||
    typeof value === "number" ||
    typeof value === "boolean"
  )
}

/**
 * A generic, kind-agnostic digest of one capability state: scalars survive,
 * bulk is replaced by counts, so a listing can carry every element's state
 * inside one response.
 *
 * Reading is pull-based: `digest` runs only while a tool result is being
 * produced, never on render or registration, so it stays off every hot path.
 */
export function digest(state: CapabilityState): Record<string, unknown> {
  const out: Record<string, unknown> = {}
  for (const [key, value] of Object.entries(state)) {
    if (Array.isArray(value)) {
      out[key] =
        value.length <= DIGEST_ARRAY_LIMIT && value.every(isScalar)
          ? value
          : { items: value.length }
    } else if (isRecord(value)) {
      out[key] = { fields: Object.keys(value).length }
    } else if (typeof value === "string" && value.length > DIGEST_STRING_LIMIT) {
      out[key] = `${value.slice(0, DIGEST_STRING_LIMIT)}…`
    } else {
      out[key] = value
    }
  }
  return out
}

/**
 * Serialise a tool result for the agent. WebMCP requires string output.
 *
 * A result is serialised as-is; one above the budget is refused with a
 * message that names the tool and asks the agent to narrow its request.
 * State-carrying results are windowed to fit before they reach here (see
 * `serialiseStateResult`); `ui_list` cannot refuse — a listing that lists
 * nothing leaves the agent with no way forward — so it reduces its document
 * instead (see `serialiseListDocument`).
 */
function serialise(toolName: string, value: unknown): string {
  const json = JSON.stringify(value)
  if (json.length <= MAX_OUTPUT) return json
  return JSON.stringify({
    ok: false,
    error: {
      code: "output_too_large",
      message: `The result of "${toolName}" is ${json.length} characters, above this page's ${MAX_OUTPUT} character output budget. Narrow the request and try again.`,
    },
  })
}

/**
 * The tool that performs one (kind, action) pair, built from the same table
 * that creates the tools. A listing therefore cannot name a tool that does not
 * exist, or miss one that does.
 */
const KIND_TOOL_NAMES = new Map(
  KIND_TOOLS.map((def) => [`${def.kind}\u0000${def.action}`, def.name] as const),
)

/**
 * How to write one kind's value: the action, and the single input property
 * that carries the value. Derived from the `sets` flag on the tool table, so
 * a kind cannot be fillable in one place and not the other, and the property
 * name can never drift from the tool an agent would otherwise call.
 */
const VALUE_SETTERS = new Map<string, { action: string; argument: string }>(
  KIND_TOOLS.filter((def) => def.sets).map((def) => {
    const [argument, ...rest] = Object.keys(def.inputSchema)
    if (argument === undefined || rest.length > 0) {
      throw new Error(
        `Agent UI: "${def.name}" is marked as setting a value but takes ${
          rest.length + (argument === undefined ? 0 : 1)
        } arguments; a value setter takes exactly one.`,
      )
    }
    return [def.kind, { action: def.action, argument }]
  }),
)

/** One element of the `ui_list` document. */
interface ListElement {
  id: string
  kind: string
  label?: string
  description?: string
  /** The tools that act on this element, by the name an agent calls. */
  tools?: string[]
  /** The component's own summary when it provides one, else the state digest. */
  state?: string | Record<string, unknown>
  children?: ListElement[]
  /**
   * Set instead of `children` when the output budget dropped them: the count,
   * the targeted `ui_list` call that recovers them, and the offset to
   * continue from when that listing is itself windowed, so honesty always
   * comes with a way to act on it.
   */
  childrenOmitted?: string
}

/** The `ui_list` response: the page header plus every live element. */
interface ListDocument {
  ok: true
  action: "list"
  /** Present only in a targeted listing: the element whose children are listed. */
  target?: string
  page?: { title?: string; description?: string }
  elements: ListElement[]
  /**
   * Present only when the elements were cut — by the caller's offset/limit or
   * by the reduction's final step — so a cut listing can be walked the same
   * way a windowed `ui_read` can.
   */
  window?: { offset: number; returned: number; total: number }
}

function* eachElement(elements: ListElement[]): Generator<ListElement> {
  for (const element of elements) {
    yield element
    if (element.children) yield* eachElement(element.children)
  }
}

/**
 * Build the `ui_list` document: the page header taken from the mounted `page`
 * capability, if any, and every other live capability as an element carrying
 * its current state, nested under the capability its `owner` names.
 *
 * With `target`, the document carries that element's children instead of the
 * whole page — the recovery an element's `childrenOmitted` marker names. The
 * target itself is not repeated: the agent already has it from the listing
 * that named it. A live target with no children lists as an empty document,
 * and the caller resolves `target` through the registry, so an unknown id is
 * rejected with the registry's own message.
 *
 * Element states are read here, at listing time. Reading is pull-based —
 * nothing reads capability state on render or registration — so a listing
 * stays off every hot path.
 */
function buildListDocument(
  registry: CapabilityRegistry,
  target?: string,
): ListDocument {
  const capabilities = registry.list()
  const doc: ListDocument = { ok: true, action: "list", elements: [] }

  if (target !== undefined) {
    doc.target = target
  } else {
    // The page is the document's header, not an element of it. Several page
    // capabilities is a page bug: use the first and leave the rest out.
    const pages = capabilities.filter((capability) => capability.kind === "page")
    const page = pages[0]
    if (page) {
      if (pages.length > 1) {
        console.error(
          "[agent-ui]",
          `Multiple capabilities of kind "page" are mounted; listing "${page.id}" as the page and leaving the rest out.`,
        )
      }
      doc.page = { title: page.label, description: page.description }
    }
  }

  const byId = new Map(
    capabilities.map((capability) => [capability.id, capability]),
  )
  const nodes = new Map<string, ListElement>()
  for (const capability of capabilities) {
    if (capability.kind === "page") continue
    // The tools that act on this element, not the internal action names. The
    // mapping is not derivable: a "data-table" is acted on by `table_filter`,
    // and a business action's only action, "run", names no tool at all. An
    // action with no tool cannot be called, so it is not listed.
    const tools =
      capability.kind === "action"
        ? readActionState(capability)
          ? [actionToolName(capability.id)]
          : []
        : [...capability.actions].flatMap((action) => {
            const name = KIND_TOOL_NAMES.get(`${capability.kind}\u0000${action}`)
            return name === undefined ? [] : [name]
          })
    nodes.set(capability.id, {
      id: capability.id,
      kind: capability.kind,
      label: capability.label,
      description: capability.description,
      tools: tools.length > 0 ? tools : undefined,
      state: capability.summarise?.() ?? digest(capability.read()),
      children: [],
    })
  }

  // Resolve ownership against the listed elements: an element whose owner
  // names one becomes that element's child; a dangling owner — or one that
  // names the page itself — leaves the element a root, so the list never
  // silently drops an element. Roots keep registration order, and a cycle
  // cannot hang: the walk stops on any element already placed, and every
  // element is placed exactly once.
  const validOwner = (id: string): string | undefined => {
    const ownerId = byId.get(id)?.owner
    return ownerId !== undefined && ownerId !== id && nodes.has(ownerId)
      ? ownerId
      : undefined
  }
  const attached = new Set<string>()
  const place = (id: string): void => {
    if (attached.has(id)) return

    // Walk up the owner chain to where this subtree anchors: an element with
    // no valid owner, one that is already in the tree, or — in a cycle — the
    // element whose owner loops back, which becomes a root so nothing is
    // dropped.
    const chain: string[] = []
    const walking = new Set<string>()
    let current = id
    for (;;) {
      if (attached.has(current) || walking.has(current)) break
      walking.add(current)
      chain.push(current)
      const ownerId = validOwner(current)
      if (ownerId === undefined) break
      current = ownerId
    }

    // `chain` is never empty: `id` itself is pushed on the first iteration.
    const anchorId = chain.pop()!
    const anchorOwner = validOwner(anchorId)
    attached.add(anchorId)
    if (anchorOwner !== undefined && attached.has(anchorOwner)) {
      nodes.get(anchorOwner)!.children!.push(nodes.get(anchorId)!)
    } else {
      doc.elements.push(nodes.get(anchorId)!)
    }
    for (const childId of chain.reverse()) {
      attached.add(childId)
      nodes.get(validOwner(childId)!)!.children!.push(nodes.get(childId)!)
    }
  }

  for (const id of nodes.keys()) place(id)

  // An element with no children carries no `children` key at all.
  for (const node of nodes.values()) {
    if (node.children?.length === 0) delete node.children
  }

  // A targeted listing is the target's own children, resolved by the same
  // placement as the whole page's; the target's node itself is not repeated.
  if (target !== undefined) {
    doc.elements = nodes.get(target)?.children ?? []
  }

  return doc
}

/**
 * Replace an element's children with a marker that names the recovery: how
 * many there are, the targeted `ui_list` call that lists them, and — when
 * that listing is itself windowed — the offset to continue from. A bare
 * count would tell the agent children exist and leave it no way to see them.
 */
function omitChildren(element: ListElement): void {
  element.childrenOmitted = `${element.children!.length} children omitted; call ui_list with target "${element.id}" to list them; if that listing is windowed, continue from window.offset + window.returned`
  delete element.children
}

/**
 * Serialise the list document, shedding in a fixed order that keeps the most
 * navigable information when the full document exceeds the output budget:
 * the structure first, then the states, then the descriptions, then the
 * elements themselves. Each step re-serialises and returns as soon as the
 * result fits. The last step always fits — it can keep a single element — so
 * `ui_list` never returns an empty listing while capabilities exist.
 *
 * The caller's `offset` and `limit` window the elements the call returns —
 * the roots, or a target's children — before any shedding. Whenever those
 * elements were cut, by that window or by the final shedding step, the
 * response reports `window` — offset, returned, total — as `ui_read` does
 * over its list field, so one walk covers both tools; a complete listing
 * carries no window key.
 */
function serialiseListDocument(
  doc: ListDocument,
  offset: number | undefined,
  limit: number | undefined,
): string {
  const total = doc.elements.length
  // An offset past the end is not an error: the empty window reports the
  // true total, so the agent learns where the list ends.
  const start = Math.min(offset ?? 0, total)
  const count = limit !== undefined ? Math.min(limit, total - start) : total - start
  doc.elements = doc.elements.slice(start, start + count)
  if (start !== 0 || count !== total) {
    doc.window = { offset: start, returned: count, total }
  }

  let json = JSON.stringify(doc)
  if (json.length <= MAX_OUTPUT) return json

  // Step 2: keep each root's own children; drop everything below them.
  for (const root of doc.elements) {
    for (const child of root.children ?? []) {
      if (child.children?.length) omitChildren(child)
    }
  }
  json = JSON.stringify(doc)
  if (json.length <= MAX_OUTPUT) return json

  const everyElement = [...eachElement(doc.elements)]

  // Step 3: drop every remaining children array — after step 2, the roots' own.
  for (const element of everyElement) {
    if (element.children?.length) omitChildren(element)
  }
  json = JSON.stringify(doc)
  if (json.length <= MAX_OUTPUT) return json

  // Step 4: drop every state.
  for (const element of everyElement) delete element.state
  json = JSON.stringify(doc)
  if (json.length <= MAX_OUTPUT) return json

  // Step 5: drop every description.
  for (const element of everyElement) delete element.description
  if (doc.page) delete doc.page.description
  json = JSON.stringify(doc)
  if (json.length <= MAX_OUTPUT) return json

  // Step 6: keep only the first N elements that fit. The largest N is found by
  // bisection — a document with fewer elements is never larger. Even a single
  // element is accepted when nothing smaller exists. This is a cut like any
  // other, so the window reports it.
  const fits = (shown: number): boolean =>
    JSON.stringify({
      ...doc,
      elements: doc.elements.slice(0, shown),
      window: { offset: start, returned: shown, total },
    }).length <= MAX_OUTPUT

  let low = 1
  let high = doc.elements.length
  while (high - low > 1) {
    const mid = Math.floor((low + high) / 2)
    if (fits(mid)) low = mid
    else high = mid
  }
  doc.elements = doc.elements.slice(0, low)
  doc.window = { offset: start, returned: low, total }
  return JSON.stringify(doc)
}

function withoutTarget(input: Record<string, unknown>): Record<string, unknown> {
  const rest: Record<string, unknown> = { ...input }
  delete rest.target
  return rest
}

/**
 * `AgentAction` validates its own id, so no sanitising or truncation is needed
 * here - a name that could collide would be a developer error the component
 * already refuses.
 */
function actionToolName(id: string): string {
  return `action_${id}`
}

function buildInputSchema(
  properties: Record<string, unknown>,
): AgentTool["inputSchema"] {
  return {
    type: "object",
    properties: { target: TARGET_PROPERTY, ...properties },
    required: ["target", ...Object.keys(properties)],
    additionalProperties: false,
  }
}

function makeExecutor(
  toolName: string,
  run: (input: Record<string, unknown>) => Promise<string>,
): AgentTool["execute"] {
  return async (input: Record<string, unknown>): Promise<string> => {
    try {
      return await run(input)
    } catch (error) {
      // A refusal travels in the returned result, never as a thrown error.
      // Chrome's WebMCP discards a thrown error's message entirely — the agent
      // is told only "Tool was executed but the invocation failed" — and these
      // messages exist to be read and acted on.
      if (error instanceof CapabilityError) {
        return serialise(toolName, {
          ok: false,
          error: { code: error.code, message: error.message },
        })
      }
      // Any other thrown value is a bug in the page. Log the full error for
      // debugging; return only a neutral message that names the tool.
      console.error("[agent-ui]", error)
      return serialise(toolName, {
        ok: false,
        error: {
          code: "internal",
          message: `The "${toolName}" tool could not complete.`,
        },
      })
    }
  }
}

function createListTool(registry: CapabilityRegistry): AgentTool {
  return {
    name: "ui_list",
    description:
      "List the agent-operable UI elements on the page. Call this first: it gives each element's id, its current state, and the tools that act on it — pass that id as target, except an action_<id> tool, which names its element. Pass target to list one element's children instead, the recovery when an element reports childrenOmitted. A cut listing reports window — walk by advancing offset by window.returned. A listed state is current; use ui_read for detail the digest leaves out.",
    scope: { on: "page" },
    inputSchema: {
      type: "object",
      properties: {
        target: {
          type: "string",
          description:
            "An element id: given, the tool lists that element's children instead of the whole page. Use it on an element that reports childrenOmitted.",
        },
        offset: {
          type: "integer",
          minimum: 0,
          description: "Index of the first element to return. Defaults to 0.",
        },
        limit: {
          type: "integer",
          minimum: 1,
          description: "How many elements to return. Defaults to as many as fit.",
        },
      },
      required: [],
      additionalProperties: false,
    },
    annotations: { readOnlyHint: true },
    execute: makeExecutor("ui_list", async (input) => {
      const target = expectOptionalString(input, "target")
      const offset = expectOptionalInteger(input, "offset", 0)
      const limit = expectOptionalInteger(input, "limit", 1)
      if (target !== undefined) {
        // Resolve through the registry so an unknown id is refused with the
        // same correctable message every other tool produces. `require`
        // rather than `read`: a targeted listing carries the children, not
        // the target's state, and reading a five-hundred-row table to
        // discard it would put the table's size on this call's cost.
        registry.require(target)
      }
      return serialiseListDocument(buildListDocument(registry, target), offset, limit)
    }),
  }
}

/**
 * An optional integer tool argument. The JSON Schema already declares the
 * shape; this enforces it at execution time, where a host may not have.
 */
function expectOptionalInteger(
  input: Record<string, unknown>,
  key: string,
  minimum: number,
): number | undefined {
  const value = input[key]
  if (value === undefined) return undefined
  if (typeof value !== "number" || !Number.isInteger(value) || value < minimum) {
    throw new CapabilityError(
      "invalid_input",
      `"${key}" must be a whole number of at least ${minimum}.`,
    )
  }
  return value
}

/** The window reported next to a state whose largest list was cut to fit. */
interface ReadWindow {
  field: string
  offset: number
  returned: number
  total: number
}

/**
 * A tool result that carries the state of the element it acted on or read.
 * Every tool except `ui_list` returns one; `window` is added by
 * `serialiseStateResult` when the state's largest list had to be cut.
 */
interface StateResult {
  ok: true
  target: string
  action: string
  state: CapabilityState
  detail?: unknown
  window?: ReadWindow
}

/**
 * Serialise a result that carries a capability state, windowing the state's
 * largest array field when the whole result exceeds the output budget.
 *
 * A result that answers a large table with nothing at all is the one answer
 * that cannot be acted on, so an oversized state is not refused outright: the
 * largest array field — measured by serialised length, the same measure as the
 * budget — is cut to the largest window that fits, and the window is reported
 * next to the state. `window.total` is the true total and `offset` walks the
 * list, so paging never has to be discovered by trial. A state with no array
 * to window cannot be reduced and is returned as-is, refusal still possible;
 * a state whose entries cannot fit even alone is genuinely unrepresentable
 * and is refused, naming the field.
 *
 * Only `ui_read` takes an offset or limit. Every other tool that carries a
 * state — kind tools and business actions — is windowed from the start of
 * the field: the action answers with what fits, and the agent walks the rest
 * with `ui_read`.
 */
function serialiseStateResult(
  toolName: string,
  result: StateResult,
  offset: number | undefined,
  limit: number | undefined,
): string {
  const { state } = result
  let best: { field: string; array: unknown[]; size: number } | undefined
  for (const [key, value] of Object.entries(state)) {
    if (!Array.isArray(value)) continue
    const size = JSON.stringify(value).length
    if (best === undefined || size > best.size) {
      best = { field: key, array: value, size }
    }
  }

  // No list to window: nothing can be reduced, so the result goes out as-is.
  if (best === undefined) {
    return serialise(toolName, result)
  }
  const { field, array } = best

  const total = array.length
  // An offset past the end is not an error: the empty window reports the true
  // total, so the agent learns where the list ends.
  const start = Math.min(offset ?? 0, total)
  const remaining = total - start
  const requested = limit !== undefined ? Math.min(limit, remaining) : remaining

  const windowed = (count: number): StateResult => ({
    ...result,
    state: { ...state, [field]: array.slice(start, start + count) },
    window: { field, offset: start, returned: count, total } satisfies ReadWindow,
  })
  const fits = (count: number): boolean =>
    JSON.stringify(windowed(count)).length <= MAX_OUTPUT

  // Asked for the list from the start with no cap: the result can go out
  // whole, with no window key, when it fits.
  if (start === 0 && requested === total) {
    const json = JSON.stringify(result)
    if (json.length <= MAX_OUTPUT) return json
  }

  if (fits(requested)) return JSON.stringify(windowed(requested))

  // A single entry that cannot fit even alone is a genuinely unrepresentable
  // state, not something to paper over with an empty window.
  if (!fits(1)) {
    return JSON.stringify({
      ok: false,
      error: {
        code: "output_too_large",
        message: `The state of "${result.target}" cannot be returned: even a single entry of its "${field}" list does not fit in this page's ${MAX_OUTPUT} character output budget.`,
      },
    })
  }

  // Bisect for the largest window that fits: `fits(low)` holds, `fits(high)`
  // does not, and the loop ends with them adjacent.
  let low = 1
  let high = requested
  while (high - low > 1) {
    const mid = Math.floor((low + high) / 2)
    if (fits(mid)) low = mid
    else high = mid
  }
  return JSON.stringify(windowed(low))
}

function createReadTool(registry: CapabilityRegistry): AgentTool {
  return {
    name: "ui_read",
    description:
      "Read the current semantic state of one UI element by id; use ui_list first for valid ids. Actions already return the element's post-change state, so this is for detail an action result windowed away and for elements you did not just act on. A long largest list comes back windowed: window reports the field, offset, returned count and true total; window.returned is authoritative when the budget clamps a limit. Walk by advancing offset by window.returned until offset + returned reaches total.",
    scope: { on: "any-capability" },
    inputSchema: {
      type: "object",
      properties: {
        target: TARGET_PROPERTY,
        offset: {
          type: "integer",
          minimum: 0,
          description:
            "Index of the first entry to return from this element's largest list. Defaults to 0.",
        },
        limit: {
          type: "integer",
          minimum: 1,
          description:
            "How many entries of that list to return. Defaults to as many as fit; the output budget may clamp it, and window.returned reports what actually returned.",
        },
      },
      required: ["target"],
      additionalProperties: false,
    },
    annotations: { readOnlyHint: true },
    execute: makeExecutor("ui_read", async (input) => {
      const target = expectString(input, "target")
      const offset = expectOptionalInteger(input, "offset", 0)
      const limit = expectOptionalInteger(input, "limit", 1)
      // The registry owns target resolution and its rejection message.
      const state = registry.read(target)
      return serialiseStateResult(
        "ui_read",
        { ok: true, target, action: "read", state },
        offset,
        limit,
      )
    }),
  }
}

/**
 * Appended to every mutating tool's description — kind tools and business
 * actions alike. Every action already returns the canonical post-commit
 * state, so reading the same element again repeats what the agent is
 * holding; the only reasons left to read are detail the result's window cut
 * away and elements the action did not touch.
 */
const ACTION_RESULT_SUFFIX =
  " The result carries the element's full state after the change, so a follow-up ui_read on the same element is unnecessary; when the result reports window, walk the rest with ui_read by advancing offset by window.returned."

/**
 * Fill several elements in one call.
 *
 * A person types into a form one field at a time; an agent that must do the
 * same pays a round trip per field, and a form is where an admin page spends
 * most of its interaction. Each value here still travels through that
 * element's own action — the same path its own tool takes, and the same path
 * a person's typing takes — so every field visibly fills and the application
 * sees each change exactly as it always did. What is saved is the round
 * trips, not the visibility.
 *
 * Every id is resolved and checked before anything is written: an unknown id,
 * or one whose kind holds no value, refuses the whole call and changes
 * nothing. A failure part-way through is a different matter — the fields
 * before it are already set, and the result says which.
 */
function createFillTool(registry: CapabilityRegistry): AgentTool {
  const fillable = [...VALUE_SETTERS.keys()].join(", ")
  return {
    name: "ui_fill",
    description:
      `Fill several elements in one call — a form's fields, say. values maps an element id to its new value: a string for an input, select or tabs, a boolean for a checkbox, an array for a multi-select. Fillable kinds: ${fillable}. Each value travels through that element's own action, so the page reacts as it does to that tool. Every id is checked first, so one bad id changes nothing. Submitting is a separate press.`,
    scope: { on: "any-capability" },
    inputSchema: {
      type: "object",
      properties: {
        values: {
          type: "object",
          description:
            "An object mapping element ids to their new values. Call ui_list for valid ids and kinds.",
          additionalProperties: true,
        },
      },
      required: ["values"],
      additionalProperties: false,
    },
    execute: makeExecutor("ui_fill", async (input) => {
      const values = expectRecord(input, "values")
      const entries = Object.entries(values)
      if (entries.length === 0) {
        rejectState('"values" must name at least one element to fill.')
      }

      // Resolve everything first. Half a form filled from a call that could
      // never have completed is worse than a call that did nothing.
      const plan = entries.map(([id, value]) => {
        // The registry owns target resolution and its rejection message.
        const capability = registry.require(id)
        const setter = VALUE_SETTERS.get(capability.kind)
        if (setter === undefined) {
          rejectState(
            `"${id}" is a ${capability.kind} and holds no value to fill. ui_fill accepts: ${fillable}. Use that element's own tool instead.`,
          )
        }
        return { id, value, ...setter }
      })

      const applied: { target: string; state: Record<string, unknown> }[] = []
      for (const { id, action, argument, value } of plan) {
        try {
          const result = await registry.invoke(id, action, { [argument]: value })
          applied.push({ target: id, state: digest(result.state) })
        } catch (error) {
          if (!(error instanceof CapabilityError)) throw error
          const done = applied.map((entry) => entry.target).join(", ")
          return serialise("ui_fill", {
            ok: false,
            error: {
              code: error.code,
              message:
                applied.length === 0
                  ? `Filling "${id}" failed and nothing was changed. ${error.message}`
                  : `Filling "${id}" failed. ${error.message} These were set before it and are still set: ${done}.`,
            },
            applied,
          })
        }
      }

      // Digests, not full states: a fill touches many elements, and the one
      // an agent wants in detail is a `ui_read` away.
      return serialise("ui_fill", { ok: true, action: "fill", applied })
    }),
  }
}

function createKindTool(
  registry: CapabilityRegistry,
  def: KindToolDef,
): AgentTool {
  return {
    name: def.name,
    description: def.description + ACTION_RESULT_SUFFIX,
    scope: { on: "kind", kind: def.kind, action: def.action },
    inputSchema: buildInputSchema(def.inputSchema),
    // Every kind tool mutates component state; reads go through ui_read.
    execute: makeExecutor(def.name, async (input) => {
      const target = expectString(input, "target")
      const actionInput = withoutTarget(input)
      const result = await registry.invoke(target, def.action, actionInput)
      // The post-commit state is the answer, not a courtesy: windowing it
      // exactly as a read windows keeps an action on a large element inside
      // the output budget instead of failing where a read would have
      // succeeded. No offset or limit here; the agent walks the rest with
      // ui_read.
      return serialiseStateResult(
        def.name,
        {
          ok: true,
          target,
          action: def.action,
          state: result.state,
          detail: result.detail,
        },
        undefined,
        undefined,
      )
    }),
  }
}

/**
 * Shape an `AgentAction` capability reports through `read()`. `Capability.read`
 * is typed as an open record, so the contract is narrowed here rather than cast.
 */
interface ActionCapabilityState {
  description: string
  inputSchema?: Record<string, unknown>
  requiresConfirmation: boolean
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value)
}

function readActionState(capability: Capability): ActionCapabilityState | undefined {
  const state = capability.read()
  if (typeof state.description !== "string" || state.description.length === 0) {
    return undefined
  }
  return {
    description: state.description,
    inputSchema: isRecord(state.inputSchema) ? state.inputSchema : undefined,
    requiresConfirmation: state.requiresConfirmation === true,
  }
}

function createActionTool(
  registry: CapabilityRegistry,
  capability: Capability,
  state: ActionCapabilityState,
): AgentTool {
  const name = actionToolName(capability.id)
  const userInputSchema = state.inputSchema ?? {}

  // A business action tool is bound to exactly one capability, so it carries no
  // `target`: the tool name already identifies what it operates on.
  const properties: Record<string, unknown> = { ...userInputSchema }
  const required = Object.keys(userInputSchema)

  if (state.requiresConfirmation) {
    properties.confirmed = {
      type: "boolean",
      description: "Set to true to confirm this consequential action.",
    }
    required.push("confirmed")
  }

  return {
    name,
    description: state.description + ACTION_RESULT_SUFFIX,
    scope: { on: "capability", id: capability.id },
    inputSchema: {
      type: "object",
      properties,
      required,
      additionalProperties: false,
    },
    // Business actions are never read-only.
    execute: makeExecutor(name, async (input) => {
      const result = await registry.invoke(capability.id, "run", input)
      // Windowed exactly as a kind tool's result is; see serialiseStateResult.
      return serialiseStateResult(
        name,
        {
          ok: true,
          target: capability.id,
          action: "run",
          state: result.state,
          detail: result.detail,
        },
        undefined,
        undefined,
      )
    }),
  }
}

/** Every tool that the currently mounted capabilities justify. */
export function createAgentTools(registry: CapabilityRegistry): AgentTool[] {
  const tools: AgentTool[] = [createListTool(registry), createReadTool(registry)]

  const mountedKinds = new Set(registry.listKinds())
  // Only worth its place in the tool list when the page holds something that
  // can be filled.
  if ([...VALUE_SETTERS.keys()].some((kind) => mountedKinds.has(kind))) {
    tools.push(createFillTool(registry))
  }
  for (const def of KIND_TOOLS) {
    if (mountedKinds.has(def.kind)) {
      tools.push(createKindTool(registry, def))
    }
  }

  for (const capability of registry.listByKind("action")) {
    const state = readActionState(capability)
    if (!state) {
      // Only AgentAction produces this kind, and it validates its own props, so
      // this means something else registered kind "action" with a state that is
      // not an action. Report it and expose no tool for it rather than
      // advertising an action with no description.
      console.error(
        "[agent-ui]",
        `Capability "${capability.id}" registered as kind "action" without a description.`,
      )
      continue
    }
    tools.push(createActionTool(registry, capability, state))
  }

  return tools
}

"use client"

/**
 * Agent UI - React view of the live capability registry.
 *
 * The registry owns the snapshot, so this hook is a direct
 * `useSyncExternalStore` over it. Caching the snapshot here instead would go
 * stale whenever the registry changed while no component was subscribed.
 */

import * as React from "react"

import type { CapabilityDescriptor } from "./capability"
import { getCapabilityRegistry } from "./registry"

/** No capabilities exist during SSR: nothing has mounted yet. */
const SERVER_SNAPSHOT: CapabilityDescriptor[] = []

export function useCapabilities(): CapabilityDescriptor[] {
  const registry = getCapabilityRegistry()

  return React.useSyncExternalStore(
    registry.subscribe,
    registry.describeAll,
    () => SERVER_SNAPSHOT,
  )
}

"use client"

/**
 * Agent UI - React binding.
 *
 * Translates component-native behaviour into semantic capability actions.
 * React remains the canonical state owner: nothing here stores a copy of
 * component state, and every action result is read back from the component
 * after the application has committed the transition.
 */

import * as React from "react"

import { useAgentContainer } from "./agent-container"
import type { Capability, CapabilityResult, CapabilityState } from "./capability"
import { CapabilityError } from "./capability"
import { getAgentUIRuntime } from "./runtime"

/** Value of the `agent` prop that every agent-operable component accepts. */
export type AgentConfig = {
  /** Stable identity. Omit to receive a document-local generated identity. */
  id?: string
  /** Human-meaningful name the agent sees in discovery. */
  label?: string
  /** What this specific element is for, one sentence. */
  description?: string
  /** id of the capability that contains this one, when it is nested. */
  owner?: string
}

export type AgentProp = AgentConfig | boolean

export type ActionMap<Actions extends Record<string, unknown>> = {
  [Action in keyof Actions & string]: (
    input: Actions[Action],
  ) => unknown | Promise<unknown>
}

export interface UseCapabilityOptions<
  State extends CapabilityState,
  Actions extends Record<string, unknown>,
> {
  agent?: AgentProp
  kind: string
  /** Label used when the `agent` prop does not carry one. */
  defaultLabel?: string
  /** What this specific element is for, used when the `agent` prop does not carry one. */
  description?: string
  /** id of the containing capability, used when the `agent` prop does not carry one. */
  owner?: string
  /**
   * One-line digest of current state, when the component can say it better
   * than a generic formatter can.
   */
  summarise?: () => string
  read: () => State
  actions: ActionMap<Actions>
}

export interface CapabilityHandle {
  /**
   * Resolved identity, or undefined when the component opted out or has not
   * registered yet — identity is resolved at registration, never during
   * render.
   */
  id: string | undefined
  registered: boolean
}

/**
 * Resolves once React has had the chance to run the work an action scheduled.
 *
 * React's scheduler performs its work on a host task, and which host task
 * differs by environment: a `MessageChannel` message in browsers, a
 * `setImmediate` callback under Node. Two turns of the task queue land after
 * either. This is only the floor for the case where nothing commits at all,
 * because a real commit resolves the waiter the instant it happens, so the
 * bound costs the accepted path nothing.
 *
 * An update the application deliberately defers with `startTransition` can
 * still commit later than this. Reporting the state as it actually stands at
 * that moment is the honest answer, not something to compensate for.
 */
function afterReactFlush(): Promise<void> {
  return new Promise((resolve) => {
    setTimeout(() => setTimeout(resolve, 0), 0)
  })
}

function resolveConfig(agent: AgentProp | undefined): AgentConfig | undefined {
  if (agent === false) return undefined
  if (agent === true || agent === undefined) return {}
  return agent
}

/**
 * Matches the shapes React's `useId()` produces — `«r1»`, `:r1:` and `_r_1_`
 * — including ids composed from one, such as shadcn Form's
 * `_r_57_-form-item`. The counter is base-32, so letters join the digits as
 * it advances (`_r_e_`), and hydration spells the marker uppercase
 * (`_R_1H1_`); the match is case-insensitive to cover both.
 *
 * Such an id is derived from the component's position in the React tree: it
 * changes whenever anything above the component changes and means nothing.
 * It is the very instability an agent-facing identity exists to escape, so it
 * is never adopted — an element carrying one is treated as carrying no id at
 * all, and identity falls through to the label-derived form.
 */
const REACT_GENERATED_ID = /«r[0-9a-v]+»|:r[0-9a-v]+:|_r_[0-9a-v]+_/i

function isReactGeneratedId(id: string): boolean {
  return REACT_GENERATED_ID.test(id)
}

export function useCapability<
  State extends CapabilityState,
  Actions extends Record<string, unknown>,
>(options: UseCapabilityOptions<State, Actions>): CapabilityHandle {
  const { agent, kind, defaultLabel, description, owner, summarise, read, actions } =
    options

  const config = resolveConfig(agent)
  // The binding asks the runtime for the registry and knows nothing about
  // any protocol. Lookup is pure: it creates the runtime object and connects
  // nothing.
  const runtime = getAgentUIRuntime()
  const { registry } = runtime
  // The instance seed React assigned to this component. It is stable for the
  // component's lifetime, which is what lets the registry hand a
  // re-registering instance back the derived id it held before.
  const seed = React.useId()
  const container = useAgentContainer()
  const explicitLabel = config?.label
  const containerItemLabel = container?.itemLabel
  const containerItemKey = container?.itemKey
  // The `agent` prop wins over the option, exactly as it does for `label`.
  const resolvedDescription = config?.description ?? description
  // The `agent` prop wins over the option, and the option over the container
  // the capability was rendered inside.
  const resolvedOwner = config?.owner ?? owner ?? container?.ownerId
  // An explicit `agent.id` always wins — but an id in React's generated shape
  // is never adopted, whichever channel carried it in: an application that
  // forwards one is forwarding the same position-derived instability the
  // element-id channel must reject.
  const explicitId =
    config?.id !== undefined && !isReactGeneratedId(config.id) ? config.id : undefined
  const enabled = config !== undefined

  // The label the capability registers under. An explicit `agent.label` wins
  // over everything. Otherwise, when a container names the position this
  // capability occupies, the label is composed as
  // `${itemLabel} — ${defaultLabel}` — "row 3: ada@lovelace.dev — Checkbox".
  // A container whose position name lives in mounted text supplies a
  // resolver, so the composition runs when the capability registers, never
  // during render. With no container, `defaultLabel` is used unchanged.
  const resolveLabel = React.useCallback((): string | undefined => {
    if (explicitLabel !== undefined) return explicitLabel
    const itemLabel =
      typeof containerItemLabel === "function"
        ? containerItemLabel()
        : containerItemLabel
    if (itemLabel === undefined) return defaultLabel
    return defaultLabel === undefined
      ? itemLabel
      : `${itemLabel} — ${defaultLabel}`
  }, [explicitLabel, containerItemLabel, defaultLabel])

  // The source the capability's id is derived from, mirroring `resolveLabel`
  // with the container's `itemKey` in `itemLabel`'s place: the label may name
  // a position ("row 3: ada@lovelace.dev — Checkbox"), which is right for
  // display and wrong for identity, while the key names the item and nothing
  // else. A container that supplies a key whose resolver resolves to nothing
  // — a table row whose every cell is empty — leaves no stable identity to
  // derive, and the capability falls to the generated form rather than
  // carrying a position in its id.
  const resolveIdentitySource = React.useCallback((): string | undefined => {
    if (explicitLabel !== undefined) return explicitLabel
    const itemKey =
      typeof containerItemKey === "function" ? containerItemKey() : containerItemKey
    if (containerItemKey !== undefined && itemKey === undefined) return undefined
    if (itemKey !== undefined) {
      return defaultLabel === undefined ? itemKey : `${itemKey} — ${defaultLabel}`
    }
    return resolveLabel()
  }, [explicitLabel, containerItemKey, defaultLabel, resolveLabel])

  const actionKey = Object.keys(actions).sort().join(" ")
  const actionNames = React.useMemo(
    () => actionKey.split(" ").filter(Boolean) as (keyof Actions & string)[],
    [actionKey],
  )

  const readRef = React.useRef(read)
  const actionsRef = React.useRef(actions)
  const summariseRef = React.useRef(summarise)
  const commitWaiters = React.useRef(new Set<() => void>())

  // Runs on every commit, before passive effects. Afterwards the refs hold the
  // committed render's closures, so a capability read always sees canonical
  // state rather than the state captured at registration time.
  React.useLayoutEffect(() => {
    readRef.current = read
    actionsRef.current = actions
    summariseRef.current = summarise
    if (commitWaiters.current.size === 0) return
    const pending = [...commitWaiters.current]
    commitWaiters.current.clear()
    for (const resolve of pending) resolve()
  })

  const waitForCommit = React.useCallback(() => {
    return new Promise<void>((resolve) => {
      let settled = false
      const finish = () => {
        if (settled) return
        settled = true
        commitWaiters.current.delete(finish)
        resolve()
      }
      commitWaiters.current.add(finish)
      // No commit means the application did not accept the transition. Resolve
      // once React's scheduled work for this tick has run, so the result
      // reports the real, unchanged state instead of a manufactured success.
      void afterReactFlush().then(finish)
    })
  }, [])

  // Identity is a registration-time fact: it is resolved here, in the effect,
  // never during render — a container's item key lives in text that only
  // exists once the subtree is mounted, and the registry's discriminator
  // bookkeeping is a side effect a render must not run. The resolved id is
  // held in state so the handle can report it; a container that needs its id
  // during render (to name itself as owner) receives undefined for the first
  // pass, and its descendants re-register once the owner context carries the
  // real id.
  const [registeredId, setRegisteredId] = React.useState<string | undefined>(
    undefined,
  )

  React.useEffect(() => {
    if (!enabled) return

    // The adapter is connected because a capability committed, so a
    // discarded render connects nothing and `agent={false}` connects nothing.
    runtime.activate()

    // Identity precedence: an explicit `agent.id` wins; otherwise the id is
    // derived from what the capability can say about itself, scoped by its
    // owner; with nothing to say, the generated form is the last resort.
    const identitySource =
      explicitId === undefined ? resolveIdentitySource() : undefined
    const id =
      explicitId ??
      (identitySource !== undefined
        ? registry.deriveId(resolvedOwner, kind, identitySource, seed)
        : registry.createId(kind, seed))

    const capability: Capability<State, Actions> = {
      id,
      kind,
      label: resolveLabel(),
      description: resolvedDescription,
      owner: resolvedOwner,
      actions: actionNames,
      read: () => readRef.current(),
      // Routed through a ref like `read`, so the registered capability always
      // calls the committed render's summarise.
      summarise: summariseRef.current
        ? () => summariseRef.current?.()
        : undefined,
      async invoke(action, input): Promise<CapabilityResult<State>> {
        const handler = actionsRef.current[action]
        if (!handler) {
          throw new CapabilityError(
            "unsupported_action",
            `"${id}" does not support "${action}". Supported actions: ${actionNames.join(", ")}.`,
          )
        }
        // 1. The component performs the transition, the application decides.
        const detail = await handler(input)
        // 2. React commits whatever the application decided.
        await waitForCommit()
        // 3. The result is canonical state, read after the commit.
        return { state: readRef.current(), detail }
      },
    }

    const unregister = registry.register(capability as Capability)
    setRegisteredId(id)
    return () => {
      unregister()
      setRegisteredId(undefined)
    }
  }, [
    enabled,
    runtime,
    registry,
    explicitId,
    kind,
    resolveLabel,
    resolveIdentitySource,
    resolvedDescription,
    resolvedOwner,
    actionNames,
    waitForCommit,
    seed,
  ])

  return { id: registeredId, registered: registeredId !== undefined }
}

"use client"

import * as React from "react"

export function useControllableState<T>(options: {
  prop: T | undefined
  defaultProp: T
  onChange?: (value: T) => void
  /**
   * Whether the application owns the value. Defaults to `prop !== undefined`,
   * which is how every primitive with a distinct empty value spells it. A
   * primitive whose empty value *is* `undefined` cannot say it that way and
   * passes the switch explicitly.
   */
  controlled?: boolean
}): [T, (next: T) => void] {
  const { prop, defaultProp, onChange, controlled } = options

  const isControlled = controlled ?? prop !== undefined

  const [internal, setInternal] = React.useState<T>(defaultProp)
  const value = isControlled ? (prop as T) : internal

  const latest = React.useRef({ isControlled, onChange })
  React.useLayoutEffect(() => {
    latest.current = { isControlled, onChange }
  })

  const setValue = React.useCallback(
    (next: T) => {
      if (!latest.current.isControlled) {
        setInternal(next)
      }
      latest.current.onChange?.(next)
    },
    [],
  )

  return [value, setValue]
}

"use client"

import * as React from "react"

/**
 * Assigns a single node to every ref it was given and returns a callback
 * whose identity stays stable while those refs are unchanged.
 *
 * A fresh callback on every render makes React call the previous ref callback
 * with null and the new one with the node, tearing down and re-attaching every
 * ref — including refs the caller passed in — even when nothing moved.
 * useCallback with the refs as dependencies keeps the identity stable until a
 * ref actually changes.
 */
export function useMergedRef<T>(
  ...refs: (React.Ref<T> | undefined)[]
): React.RefCallback<T> {
  return React.useCallback(
    (value: T | null) => {
      for (const ref of refs) {
        if (!ref) continue
        if (typeof ref === "function") {
          ref(value)
        } else {
          ref.current = value
        }
      }
    },
    [...refs],
  )
}

/**
 * Agent UI — input validation.
 *
 * Agent input is untrusted. These helpers reject invalid requests with
 * messages an agent can self-correct from. They never coerce, never guess and
 * never compensate for a missing semantic.
 */

import { CapabilityError } from "./capability"

function reject(message: string): never {
  throw new CapabilityError("invalid_input", message)
}

export function expectObject(input: unknown): Record<string, unknown> {
  if (typeof input !== "object" || input === null || Array.isArray(input)) {
    reject("Arguments must be an object.")
  }
  return input as Record<string, unknown>
}

export function expectString(input: unknown, field: string): string {
  const value = expectObject(input)[field]
  if (typeof value !== "string") reject(`"${field}" must be a string.`)
  return value
}

export function expectOptionalString(input: unknown, field: string): string | undefined {
  const value = expectObject(input)[field]
  if (value === undefined || value === null) return undefined
  if (typeof value !== "string") reject(`"${field}" must be a string.`)
  return value
}

export function expectRecord(input: unknown, field: string): Record<string, unknown> {
  const value = expectObject(input)[field]
  if (typeof value !== "object" || value === null || Array.isArray(value)) {
    rejectState(`"${field}" must be an object.`)
  }
  return value as Record<string, unknown>
}

export function expectBoolean(input: unknown, field: string): boolean {
  const value = expectObject(input)[field]
  if (typeof value !== "boolean") reject(`"${field}" must be true or false.`)
  return value
}

export function expectInteger(input: unknown, field: string, min: number): number {
  const value = expectObject(input)[field]
  if (typeof value !== "number" || !Number.isInteger(value)) {
    reject(`"${field}" must be a whole number.`)
  }
  if (value < min) reject(`"${field}" must be ${min} or greater.`)
  return value
}

export function expectStringArray(input: unknown, field: string): string[] {
  const value = expectObject(input)[field]
  if (!Array.isArray(value) || value.some((item) => typeof item !== "string")) {
    reject(`"${field}" must be an array of strings.`)
  }
  return value as string[]
}

export function expectNumberArray(input: unknown, field: string): number[] {
  const value = expectObject(input)[field]
  if (!Array.isArray(value) || value.some((item) => typeof item !== "number")) {
    reject(`"${field}" must be an array of numbers.`)
  }
  return value as number[]
}

export function expectOneOf<T extends string>(
  value: string,
  allowed: readonly T[],
  field: string,
): T {
  if (!allowed.includes(value as T)) {
    reject(`"${field}" must be one of: ${allowed.join(", ")}. Received "${value}".`)
  }
  return value as T
}

/** Rejects an action the current component state does not permit. */
export function rejectState(message: string): never {
  throw new CapabilityError("rejected", message)
}

/**
 * Agent UI - WebMCP protocol adapter.
 *
 * The only layer that touches `document.modelContext`. It translates the
 * capability registry into WebMCP tools and dispatches agent calls back
 * through the registry, never through the DOM. Tool count scales with
 * capability kinds, not component instances.
 */

import type { CapabilityRegistry } from "./registry"
import { createAgentTools, type AgentTool } from "./tools"

export function isWebMCPSupported(): boolean {
  return getModelContext() != null
}

function getModelContext(): WebMCP.ModelContext | undefined {
  if (typeof document === "undefined") return undefined
  return document.modelContext
}

/**
 * `webmcp-types@0.1.5` does not yet declare `executeTool`, which the WebMCP
 * specification puts on `ModelContext`. Narrowing it here keeps the gap in the
 * one file allowed to know about the protocol.
 *
 * The specification types the second argument as an `object` and serialises it
 * itself, but Chrome's shipping implementation takes the already-serialised
 * JSON string and rejects anything else with "Failed to parse input arguments".
 * This declares what the browser actually accepts.
 * https://developer.chrome.com/docs/ai/webmcp/imperative-api
 */
interface ModelContextWithExecute extends WebMCP.ModelContext {
  executeTool(
    tool: WebMCP.RegisteredTool,
    inputArguments?: string,
  ): Promise<string>
}

/**
 * Runs a registered tool the way an agent would: through the browser's own
 * WebMCP dispatch rather than by calling the tool definition directly.
 *
 * This exists so nothing outside the adapter has to reach for
 * `document.modelContext` (spec invariant 6). It resolves to the tool's string
 * result, and rejects when WebMCP is unavailable or the tool is not registered
 * yet.
 */
export async function executeViaWebMCP(
  name: string,
  input: Record<string, unknown>,
): Promise<string> {
  const modelContext = getModelContext() as ModelContextWithExecute | undefined
  if (!modelContext) {
    throw new Error("WebMCP is not available in this browser.")
  }
  const registered = await modelContext.getTools()
  const tool = registered.find((candidate) => candidate.name === name)
  if (!tool) {
    throw new Error(`The "${name}" tool is not registered with the browser yet.`)
  }
  return modelContext.executeTool(tool, JSON.stringify(input))
}

function toWebMCPTool(tool: AgentTool): WebMCP.ModelContextTool {
  return {
    name: tool.name,
    description: tool.description,
    inputSchema: tool.inputSchema,
    annotations: tool.annotations,
    execute: (inputObject) => tool.execute(inputObject),
  }
}

export function connectWebMCP(registry: CapabilityRegistry): () => void {
  const modelContext = getModelContext()
  if (!modelContext) {
    // Progressive enhancement (spec section 11): without WebMCP the app stays
    // ordinary React UI. Register nothing, tear down nothing.
    return () => {}
  }

  const controllers = new Map<string, AbortController>()
  let disposed = false
  let running = false
  let dirty = false

  /**
   * Brings the registered tool set in line with the registry exactly once.
   * Registration is asynchronous, so `schedule` guarantees runs never
   * interleave rather than reconciling a moving target.
   */
  const reconcile = async () => {
    const desired = createAgentTools(registry)
    const desiredNames = new Set(desired.map((tool) => tool.name))

    for (const [name, controller] of [...controllers]) {
      if (!desiredNames.has(name)) {
        controller.abort()
        controllers.delete(name)
      }
    }

    for (const tool of desired) {
      // A kept registration is always current: its execute closure reads the
      // registry live, so there is nothing to refresh and no churn to cause.
      if (controllers.has(tool.name)) continue

      const controller = new AbortController()
      try {
        await modelContext.registerTool(toWebMCPTool(tool), {
          signal: controller.signal,
        })
      } catch (error) {
        // Progressive enhancement again: a failed registration must never
        // break human interaction. This is the one place a catch is correct.
        console.warn(
          "[agent-ui]",
          `Failed to register the WebMCP tool "${tool.name}":`,
          error,
        )
        continue
      }

      if (disposed) {
        controller.abort()
        continue
      }
      controllers.set(tool.name, controller)
    }
  }

  const schedule = () => {
    if (running) {
      dirty = true
      return
    }
    running = true
    void (async () => {
      do {
        dirty = false
        await reconcile()
      } while (dirty && !disposed)
      running = false
    })()
  }

  const unsubscribe = registry.subscribe(schedule)
  schedule()

  return () => {
    disposed = true
    unsubscribe()
    for (const controller of controllers.values()) {
      controller.abort()
    }
    controllers.clear()
  }
}
